pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    let step_ratio = step_index as f64 / total_jobs as f64;
    let dynamic_factor = 1.0 + step_ratio * (1.0 - step_ratio);

    let lookahead_score = if node_residual_cpu >= next_job_cpu && node_residual_ram >= next_job_ram {
        0.5 // Perfect fit for the next job, prioritize this node
    } else {
        0.3 // No perfect fit for the next job but still a good option
    };

    let cpu_balance_bonus = (1.0 - cpu_norm).powi(2);
    let ram_balance_bonus = (1.0 - ram_norm).powi(2);
    let balance_score = cpu_balance_bonus + ram_balance_bonus;

    // Combine residual fitting with lookahead anticipation
    let residual_fit_score = (node_residual_cpu as f64 / mean_cpu_residual) * (node_residual_ram as f64 / mean_ram_residual);
    let lookahead_packing_bonus = if node_residual_cpu >= next_job_cpu && node_residual_ram >= next_job_ram {
        0.5 // Perfect fit for the next job, prioritize this node
    } else {
        0.1 // No perfect fit but still a good option
    };

    let score = cpu_norm + ram_norm + imbalance_penalty * dynamic_factor + lookahead_score + balance_score + residual_fit_score * lookahead_packing_bonus;
    score
}

